import assert from 'node:assert/strict';
import { FixedClock } from './src/physics/fixed-clock.ts';
const clock = new FixedClock();
clock.resume();
clock.advance(0.2 + 1/240,()=>{});
const discarded = clock.totalDroppedWallTimeSeconds;
assert.ok(discarded > 0);
clock.pause(); clock.setMode('recording'); clock.resume();
clock.advance(0.2,()=>{});
const debt = clock.accumulatorSeconds;
const startTick = clock.tick;
clock.resume();
const observed = [];
for(let i=1;i<=180;i++) {
 const result=clock.advanceControlledStep(()=>observed.push(clock.tick + 1));
 assert.equal(result.steps,1); assert.equal(result.tick,startTick+i);
 assert.equal(result.overrun,false); assert.equal(result.droppedWallTimeSeconds,0);
 assert.equal(clock.accumulatorSeconds,debt);
 assert.equal(clock.totalDroppedWallTimeSeconds,discarded);
}
assert.deepEqual(observed,Array.from({length:180},(_,i)=>startTick+i+1));
const boundary=clock.advanceControlledStep(()=>clock.pause());
assert.equal(boundary.steps,1);
assert.equal(clock.advanceControlledStep(()=>assert.fail('paused callback ran')).steps,0);
assert.equal(clock.accumulatorSeconds,debt);
assert.equal(clock.totalDroppedWallTimeSeconds,discarded);
console.log(JSON.stringify({status:'PASS',controlledTicks:180,startTick,endTick:boundary.tick,debtPreserved:debt,priorDiscardPreserved:discarded,pauseBoundaryCommitted:true}));
